/**
 * This dataset wrapper has been mostly generated by LLM (Claude)
 * TODO review and rewrite this for quality.
 */

import type {
  ISubscribableDataset,
  nodeEventListener,
} from "@ldo/subscribable-dataset";
import type { QuadMatch } from "@ldo/rdf-utils";
import type { Quad, Term, Dataset } from "@rdfjs/types";

type DatasetKey = keyof Dataset;

// Methods that read the whole dataset. Names come from the RDF/JS Dataset
// spec, NOT verified against ExtendedDataset. Check it for extras.
const WHOLE_READS = new Set<DatasetKey>([
  "size",
  "toArray",
  "toCanonical",
  "toStream",
  "toString",
  "forEach",
  "map",
  "reduce",
  "some",
  "every",
  "filter",
  "union",
  "intersection",
  "difference",
  "equals",
  "contains",
]);

// Every method on SubscribableDataset that mutates quads.
const WRITES = new Set<DatasetKey>([
  "add",
  "addAll",
  "delete",
  "deleteMatches",
  "import",
]);

// Methods that hand `this` to something that later reads data (verify).
const BIND_TO_PROXY = new Set<DatasetKey>(["usingType"]);

export type TrackingDataset<D> = D & { dispose(): void };

/**
 * Create a wrapping layer around subscribable dataset that keeps track of reads
 * and listens to changes when the quads being read change.
 */
export function createTrackingDataset<D extends ISubscribableDataset<Quad>>(
  dataset: D,
  listener: nodeEventListener<Quad>,
): TrackingDataset<D> {
  let disposed = false;
  const ALL: QuadMatch = [null, null, null, null];

  // Same logic as TrackingProxyContext.addListener
  const addListener = (match: QuadMatch) => {
    if (disposed) return;
    if (!dataset.listeners(match).includes(listener))
      dataset.on(match, listener);
  };

  const n = (t?: Term | null) => (t ?? null) as any;

  const proxy: any = new Proxy(dataset, {
    get(target, key, receiver) {
      if (key === "dispose")
        return () => {
          disposed = true;
        };

      if (key === "match")
        return (s?: Term, p?: Term, o?: Term, g?: Term) => {
          addListener([n(s), n(p), n(o), n(g)]);
          return target.match(s, p, o, g);
        };

      if (key === "has")
        return (q: Quad) => {
          addListener([
            q.subject as any,
            q.predicate as any,
            q.object as any,
            q.graph as any,
          ]);
          return target.has(q);
        };

      if (key === Symbol.iterator)
        return () => {
          addListener(ALL);
          return target[Symbol.iterator]();
        };

      if (WRITES.has(key))
        return () => {
          throw new Error(
            "Tracked dataset is read-only; write via the untracked dataset or a transaction.",
          );
        };

      if (BIND_TO_PROXY.has(key)) return (target as any)[key].bind(proxy);

      const value = Reflect.get(target, key, target); // internals run on the real dataset
      if (WHOLE_READS.has(key)) {
        if (typeof value === "function")
          return (...args: unknown[]) => {
            addListener(ALL);
            return value.apply(target, args);
          };
        addListener(ALL); // `size`
        return value;
      }
      return typeof value === "function" ? value.bind(target) : value;
    },
  });
  return proxy;
}
